function_name: queueWithdrawal
code:     function queueWithdrawal(uint256 amount) external nonReentrant {
        MarketState memory state = _getUpdatedState();
        Account memory account = _getAccountWithRole(msg.sender, AuthRole.WithdrawOnly);

        uint104 scaledAmount = state.scaleAmount(amount).toUint104();
        if (scaledAmount == 0) {
            revert NullBurnAmount();
        }

        account.scaledBalance -= scaledAmount;
        _accounts[msg.sender] = account;
        emit Transfer(msg.sender, address(this), amount);

        if (state.pendingWithdrawalExpiry == 0) {
            state.pendingWithdrawalExpiry = uint32(block.timestamp + withdrawalBatchDuration);
            emit WithdrawalBatchCreated(state.pendingWithdrawalExpiry);
        }
        uint32 expiry = state.pendingWithdrawalExpiry;
        WithdrawalBatch memory batch = _withdrawalData.batches[expiry];
        _withdrawalData.accountStatuses[expiry][msg.sender].scaledAmount += scaledAmount;
        batch.scaledTotalAmount += scaledAmount;
        state.scaledPendingWithdrawals += scaledAmount;
        emit WithdrawalQueued(expiry, msg.sender, scaledAmount);

        uint256 availableLiquidity = batch.availableLiquidityForPendingBatch(state, totalAssets());
        if (availableLiquidity > 0) {
            _applyWithdrawalBatchPayment(batch, state, expiry, availableLiquidity);
        }

        _withdrawalData.batches[expiry] = batch;
        _writeState(state);
    }
vulnerability: Dilution of withdrawal batch payments via new deposits into a partially paid batch
reason: The function allows any lender to add a new withdrawal to the existing pending batch as long as `state.pendingWithdrawalExpiry` is non-zero, even if that batch has already received partial payments via `_applyWithdrawalBatchPayment`. Because the pro-rata payout in `executeWithdrawal` is computed as `batch.normalizedAmountPaid * status.scaledAmount / batch.scaledTotalAmount`, adding a large new withdrawal after some liquidity has already been paid increases the denominator and dilutes the claims of earlier participants. In a distressed market, an attacker can acquire market tokens at a discount, queue a large withdrawal into the same partially paid batch, and then claim a disproportionate share of the already-paid unclaimed liquidity, stealing funds from earlier withdrawers. The fix is to prevent adding to a batch once any amount has been burned (i.e., require `batch.scaledAmountBurned == 0`) or to track per-user cumulative payments.
------------------
